1	// THE TERMINAL TRANSITION, IN CODE (#892; docs/PRINCIPLES.md).
2	// A work-item session ends by performing five ordered side effects — comment,
3	// drop `task:agent`, add the outcome label, carry the execution record, close
4	// with the right state reason — on the item it holds, and nothing else: a
5	// converge never writes to another work item (docs/PRINCIPLES.md; #1373 reversed
6	// an earlier attempt). Releasing a dependent a close may have freed is the scheduler run's
7	// job alone. Asking a session to perform these effects from prose is asking for
8	// it at the moment its context is fullest and the remaining work looks like
9	// formality; both of the first two live agentic runs got part of it wrong,
10	// silently, in different ways.
11	//
12	// THIS FILE RUNS IN ONE PLACE: INSIDE A WORK-ITEM SESSION. `public/instructions.md`
13	// step 6 is its only caller — no workflow invokes it, no module imports it. The
14	// Actions side converges through `executor.mjs`, which owns that path entirely.
15	//
16	// SO EVERY LINE HERE ASSUMES MCP, AND NOTHING HERE MAY REACH THE NETWORK. A session
17	// holds its GitHub access through its own tools; a subprocess it spawns has no route
18	// to them and none to the REST API. This file therefore PLANS a transition and
19	// PRINTS it addressed to those tools — it never performs one. Printing the calls is
20	// the successful outcome, on stdout, exit 0. That is not a fallback: it is the only
21	// path, and it must never read as a failure. A REST executor lived here once and did
22	// (#1491) — a session met its `console.error` before it met the path written for it,
23	// reported that it could not converge, and left the item to the janitor's 3h leash,
24	// which parks a finished run as a human decision. Five sampled items across five
25	// repos were exactly that.
26	//
27	// The split is the same one the executor already draws: THE SESSION SUPPLIES THE
28	// JUDGMENT — which outcome, and the prose of what happened — and the CODE decides
29	// every step of the transition. A session that stops early now leaves an item that
30	// is visibly unconverged, rather than one that looks finished and is not.
31	//
32	// Usage — the item is handed in, because this process cannot read it:
33	//   node converge-item.mjs --issue <n> --outcome <done|approval|action|decision|failure>
34	//                          --summary <text> [--pr <n>]
35	//                          --repo <owner/name> --item-file <path to the issue as JSON>
36	
37	import { readFile } from 'node:fs/promises';
38	import { pathToFileURL } from 'node:url';
39	import { renderTaskExec } from '../items/run-record.mjs';
40	import { actionsEnv } from '../world/actions.mjs';
41	import {
42	  STATUS_RUNNING_AGENT, STATUS_DONE, STATUS_NEEDS_HUMAN_ACTION, STATUS_NEEDS_HUMAN_APPROVAL,
43	  STATUS_NEEDS_HUMAN_DECISION, STATUS_NEEDS_HUMAN_FAILURE, QUEUED_LABEL, IN_REVIEW_LABEL, ORIGIN_LABELS,
44	  EPISODE_MARKER,
45	} from '../../public/task-constants.mjs';
46	import {
47	  isStatus, machineBlockOf, hasLabel, parseWorkItemTitle, parseWorkItemBody, spellingsOf,
48	  labelNames, editItemBody, withEndsWhen,
49	} from '../../public/work-item-grammar.mjs';
50	
51	// What a session may claim, and what each one means for the item. `record` is the
52	// execution-record status, and `null` means no record: an approval park is a run
53	// that SUCCEEDED and left a PR, which the record vocabulary has no word for, and
54	// a fifth status would be stored data every decoder in the fleet must learn.
55	export const OUTCOMES = Object.freeze({
56	  done: { label: STATUS_DONE, closes: true, stateReason: 'completed', record: 'success' },
57	  approval: { label: STATUS_NEEDS_HUMAN_APPROVAL, closes: false, record: null },
58	  action: { label: STATUS_NEEDS_HUMAN_ACTION, closes: false, record: 'failed' },
59	  decision: { label: STATUS_NEEDS_HUMAN_DECISION, closes: false, record: 'failed' },
60	  failure: { label: STATUS_NEEDS_HUMAN_FAILURE, closes: false, record: 'failed' },
61	});
62	
63	export function parseArgs(argv) {
64	  const args = {};
65	  for (let n = 0; n < argv.length; n += 1) {
66	    const m = /^--([a-z-]+)$/.exec(argv[n]);
67	    if (m) { args[m[1]] = argv[n + 1] ?? ''; n += 1; }
68	  }
69	  const issue = Number(args.issue);
70	  if (!Number.isInteger(issue) || issue <= 0) return { error: '--issue must be the work item\'s issue number' };
71	  if (!OUTCOMES[args.outcome]) {
72	    return { error: `--outcome must be one of ${Object.keys(OUTCOMES).join(', ')}, got ${JSON.stringify(args.outcome ?? null)}` };
73	  }
74	  if (!String(args.summary ?? '').trim()) return { error: '--summary must say what happened; it is the item\'s only durable account' };
75	  if (args.outcome === 'approval' && !args.pr) {
76	    return { error: '--pr must name the pull request an approval park is waiting on — a park nobody can act on is not a park' };
77	  }
78	  return {
79	    issue, outcome: args.outcome, summary: args.summary, pr: args.pr ? Number(args.pr) : null,
80	    repo: args.repo || null, itemFile: args['item-file'] || null,
81	  };
82	}
83	
84	// Why an item may NOT be converged by this call. Refusing loudly beats writing a
85	// terminal state onto the wrong issue: this runs from a session, whose whole
86	// notion of which item it holds came from an untrusted fire payload.
87	export function refusal(item, issue) {
88	  if (!item) return `#${issue} could not be read`;
89	  // A marked issue IS its own item (PRINCIPLES.md), so the title test cannot be the
90	  // membership test any more: what says this is one is the machine block adoption
91	  // wrote — never the body's first line, which on a marked issue is a person's prose.
92	  //
93	  // THREE SIGNALS, ANY ONE SUFFICIENT. A membership test gated on the single artifact
94	  // it exists to validate refuses exactly the items that artifact is missing from: an
95	  // issue adopted before the block delimiters existed carries its fields bare, and was
96	  // refused here into a by-hand convergence that dropped half the transition
97	  // (missingbulb/Shepherd#360). The origin label is the independent one — carried for
98	  // life, and platform-write-gated like the block was.
99	  const marked = ORIGIN_LABELS.some((name) => hasLabel(item, name));
100	  if (!parseWorkItemTitle(item.title ?? '') && machineBlockOf(item.body ?? '') === null && !marked) {
101	    return `#${issue} is not a Claudinite work item`;
102	  }
103	  if (item.state !== 'open') return `#${issue} is already closed — it was converged once already`;
104	  if (!isStatus(item, STATUS_RUNNING_AGENT)) {
105	    return `#${issue} is not with an agent (\`${STATUS_RUNNING_AGENT}\`) — this session does not hold it, so it is not this session's to converge`;
106	  }
107	  return null;
108	}
109	
110	// The record line for this item, or null where the vocabulary has no true answer.
111	export const recordLine = (item, status) => {
112	  const parsed = parseWorkItemTitle(item.title);
113	  return status && parsed
114	    ? renderTaskExec({ pack: parsed.pack, task: parsed.task, slotId: `#${item.number}`, status })
115	    : null;
116	};
117	
118	// The comment one converge writes: the session's account, then the record, so a
119	// reader and a parser both find what they came for in one place.
120	// THE EPISODE ENDS WHERE THE ITEM IS LET GO OF (F18/F24). An executor that parks
121	// an item strikes its own claim on the way out; a SESSION cannot — its claim is
122	// the executor's, and it has no edit for it — so the boundary rides its own
123	// comment instead. `claimWinner` reads the last comment carrying the marker
124	// whatever wrote it, so this is the same mechanism, not a second one.
125	//
126	// Without it every claim from the parked episode outlives the park: a person
127	// re-queues the item, the next executor claims it, and `claimWinner` hands the
128	// episode to the dead claim that is still the earliest one on the issue. The item
129	// then loses every race it will ever have — which is the livelock F18 describes,
130	// reached through the one converge that had no way to say it had let go.
131	export function convergeComment(item, { summary, pr, record, boundary = false }) {
132	  const rec = recordLine(item, record);
133	  const line = rec ? `\n\n\`\`\`\n${rec}\n\`\`\`` : '';
134	  const waiting = pr ? `\n\nWaiting on a person: merge or close #${pr}, then close this item.` : '';
135	  const ends = boundary
136	    ? `\n\n${EPISODE_MARKER}\nThis session released the item without closing it; every claim before this line is spent.`
137	    : '';
138	  return `${summary.trim()}${waiting}${line}${ends}`;
139	}
140	
141	// THE TRANSITION AS DATA (#1374). The side effects were a straight line of
142	// `await api.…` calls, which silently made REST the only way to perform them —
143	// and the sessions `invoke.mjs` hands work to have no REST route to their own
144	// repository, so the last step of every agentic run was the one step that
145	// environment could not take.
146	//
147	// So the sequence is planned as OPS and executed by whoever can. The planner is
148	// the single source of what a convergence IS; the executors differ only in
149	// transport. The session still supplies nothing but the judgment.
150	//
151	// Removes are granular and unconditional — every spelling of the status being
152	// left, not only the ones this snapshot shows (apply-status.mjs's rule: a member's
153	// items outlive its converges, so an item may wear an older engine's spelling).
154	export function convergeOps(item, plan) {
155	  const spec = OUTCOMES[plan.outcome];
156	  // A park leaves the item open for somebody else to claim, so its comment carries
157	  // the episode boundary; a close needs none — nothing re-claims a closed item.
158	  const ops = [{ kind: 'comment', issue: item.number, body: convergeComment(item, { ...plan, record: spec.record, boundary: !spec.closes }) }];
159	
160	  // The record goes to BOTH sinks, and neither is redundant: the comment above is
161	  // the durable one (Actions logs expire, the item does not), while this printed
162	  // copy lands in the session transcript, which is what the usage fold reads for
163	  // the task-status census.
164	  const rec = recordLine(item, spec.record);
165	  if (rec) ops.push({ kind: 'record', line: rec });
166	
167	  for (const label of spellingsOf(STATUS_RUNNING_AGENT)) {
168	    ops.push({ kind: 'removeLabel', issue: item.number, name: label });
169	  }
170	  // ONE label, on both paths: the outcome IS the status. A park in particular is
171	  // never a pair, so nothing can be half-applied (#1385).
172	  ops.push({ kind: 'addLabel', issue: item.number, name: spec.label });
173	
174	  // THE PARK'S END CONDITION (#1468). The comment above already tells a person to
175	  // merge or close the pull request; this says the same thing where the janitor can
176	  // read it, so the item ends when that happens instead of waiting for someone to
177	  // notice it already did. Every park that names one gets it, not only `approval`.
178	  if (!spec.closes && plan.pr) {
179	    ops.push({ kind: 'setBody', issue: item.number, body: editItemBody(item.body, (m) => withEndsWhen(m, plan.pr)) });
180	  }
181	
182	  // SUPERSEDING (PRINCIPLES.md). The executor decided at resolution which of this
183	  // task's earlier pull requests a `supersede_existing_pr` run replaces and stamped
184	  // them on the item; they close only once THIS run's own pull request exists — a
185	  // run that delivered nothing, or broke, leaves them where they were, so a review
186	  // member's pending pull request is never taken away for nothing.
187	  const { supersedes } = parseWorkItemBody(item.body ?? '');
188	  if (plan.pr && (plan.outcome === 'done' || plan.outcome === 'approval')) {
189	    for (const number of supersedes) {
190	      ops.push({ kind: 'closePull', number, successor: plan.pr, body: `Superseded by #${plan.pr}, a later run of the same task. Closing this one.` });
191	    }
192	  }
193	
194	  if (spec.closes) {
195	    // A DONE TERMINAL CLOSES THE ISSUE IT STANDS ON, marked or filed (#1489,
196	    // reversing docs/PRINCIPLES.md's "never a marked issue"). `done` is the one outcome
197	    // that means nothing is left for anyone to act on, so an issue left open under
198	    // it asks its author to come and agree with what the run already settled. Every
199	    // other outcome parks, and a park leaves the issue open to be waited on.
200	    ops.push({ kind: 'close', issue: item.number, stateReason: spec.stateReason });
201	    return ops;
202	  }
203	
204	  // A REQUEST ITEM WRITES BACK TO ITS ISSUE, on the one end that is its business
205	  // (PRINCIPLES.md). Only the approval park: a failure deliberately writes nothing and
206	  // leaves `claude-queued` standing, because re-arming work that writes code is a
207	  // person's decision and that standing label is what stops the next scheduler run
208	  // queueing a second run of the same request. Only a LEGACY shadow item writes
209	  // back to a different issue.
210	  const { request } = parseWorkItemBody(item.body ?? '');
211	  if (request && request !== item.number && plan.outcome === 'approval') {
212	    ops.push({ kind: 'comment', issue: request, body: `A pull request for this is open and waiting on you: #${plan.pr}. Merge or close it.` });
213	    ops.push({ kind: 'removeLabel', issue: request, name: QUEUED_LABEL });
214	    ops.push({ kind: 'addLabel', issue: request, name: IN_REVIEW_LABEL });
215	  }
216	  return ops;
217	}
218	
219	// THE SESSION EXECUTOR'S SCRIPT. Same ops, addressed to the GitHub tools a session
220	// does have. Two differences forced by that surface, both handled here rather than
221	// left to the session to work out:
222	//
223	//  - THERE IS NO GRANULAR LABEL WRITE. `issue_write` replaces the whole set, so the
224	//    granular removes and adds are folded into the FINAL set here, computed from the
225	//    labels this item was read with. Everything not a status label is carried through.
226	//  - THE RECORD IS PRINTED BY THE SESSION, which is where it has to be anyway: the
227	//    usage fold reads the census out of the session transcript.
228	export function sessionScript(item, plan, repo) {
229	  const [owner, name] = String(repo).split('/');
230	  const lines = [];
231	  let n = 0;
232	  const step = (s) => { n += 1; lines.push(`${n}. ${s}`); };
233	
234	  // The item's own label set can be computed exactly, because the item was read
235	  // with its labels. Any OTHER issue's cannot — so that one is emitted as a
236	  // read-modify-write naming only the change, and never as a computed set, which
237	  // would silently drop every label this process never saw.
238	  const own = new Set(labelNames(item));
239	  const foreign = [];
240	  // The body write folds into the item's own `issue_write`, which is one call
241	  // either way. A park never closes, so the step it folds into is the trailing
242	  // label write below.
243	  let newBody = null;
244	
245	  for (const op of convergeOps(item, plan)) {
246	    if (op.kind === 'comment') {
247	      step(`\`add_issue_comment\` — owner \`${owner}\`, repo \`${name}\`, issue_number \`${op.issue}\`, body exactly:\n\n<<<BODY\n${op.body}\n>>>END\n`);
248	    } else if (op.kind === 'record') {
249	      step(`Output this line, on its own, in your reply. Nothing else emits it, and the usage census is read from your transcript:\n\n    ${op.line}\n`);
250	    } else if (op.kind === 'removeLabel' || op.kind === 'addLabel') {
251	      if (op.issue === item.number) {
252	        if (op.kind === 'removeLabel') own.delete(op.name); else own.add(op.name);
253	      } else {
254	        foreign.push(op);
255	      }
256	    } else if (op.kind === 'setBody' && op.issue === item.number) {
257	      newBody = op.body;
258	    } else if (op.kind === 'close') {
259	      step(`\`issue_write\` — method \`update\`, owner \`${owner}\`, repo \`${name}\`, issue_number \`${op.issue}\`,`
260	        + ` labels \`${JSON.stringify([...own])}\`, state \`closed\`, state_reason \`${op.stateReason}\``);
261	      own.clear();
262	    } else if (op.kind === 'closePull') {
263	      step(`\`add_issue_comment\` — owner \`${owner}\`, repo \`${name}\`, issue_number \`${op.number}\` (a pull request), body exactly:\n\n<<<BODY\n${op.body}\n>>>END\n`);
264	      step(`\`update_pull_request\` — owner \`${owner}\`, repo \`${name}\`, pullNumber \`${op.number}\`, state \`closed\``);
265	    }
266	  }
267	  // A park never closed, so its label write is still owed.
268	  if (own.size) {
269	    step(`\`issue_write\` — method \`update\`, owner \`${owner}\`, repo \`${name}\`, issue_number \`${item.number}\`,`
270	      + ` labels \`${JSON.stringify([...own])}\``
271	      + (newBody === null ? '' : `, body exactly:\n\n<<<BODY\n${newBody}\n>>>END\n`));
272	  }
273	  for (const op of foreign) {
274	    step(`On #${op.issue}: ${op.kind === 'addLabel' ? 'ADD' : 'REMOVE'} the label \`${op.name}\`.`
275	      + ` Read that issue's current labels first and write them back with only this one change —`
276	      + ` \`issue_write\` replaces the whole set, and this process never saw the rest.`);
277	  }
278	  return lines.join('\n');
279	}
280	
281	async function main() {
282	  const plan = parseArgs(process.argv.slice(2));
283	  if (plan.error) {
284	    console.error(`converge-item: ${plan.error}`);
285	    process.exitCode = 2;
286	    return;
287	  }
288	
289	  // The repo this item lives in. `--repo` is what instructions.md passes; the two
290	  // environment names answer for a session whose harness sets one of them.
291	  const repo = plan.repo ?? actionsEnv().CLAUDINITE_ITEM_REPO ?? actionsEnv().GITHUB_REPOSITORY ?? null;
292	  if (!repo) {
293	    console.error('converge-item: --repo <owner/name> names the repository this item lives in');
294	    process.exitCode = 2;
295	    return;
296	  }
297	
298	  // THE ITEM IS HANDED IN. This process cannot read it — that is the whole premise
299	  // of the file — so the session reads it with its own tools and passes it through.
300	  // A file rather than an argument: an item's body is prose of arbitrary length, and
301	  // a shell-quoted one is a quoting bug waiting for the first apostrophe.
302	  // `CLAUDINITE_ITEM_JSON` stays readable for a member whose instructions.md is a
303	  // cycle behind, since a mount updates on its own schedule.
304	  const raw = plan.itemFile
305	    ? await readFile(plan.itemFile, 'utf8')
306	    : (actionsEnv().CLAUDINITE_ITEM_JSON ?? '');
307	  let item = null;
308	  try { item = JSON.parse(raw || 'null'); } catch { item = null; }
309	  if (!item) {
310	    console.error('converge-item: --item-file must hold the issue as your GitHub tools returned it'
311	      + ' (number, title, body, state, labels).\n'
312	      + `Read it first: \`issue_read\` method \`get\` on ${repo} #${plan.issue}, save the JSON, pass the path.`);
313	    process.exitCode = 2;
314	    return;
315	  }
316	
317	  const no = refusal(item, plan.issue);
318	  if (no) { console.error(`converge-item: ${no}`); process.exitCode = 1; return; }
319	
320	  // The successful outcome. Everything below is the transition, decided here and
321	  // performed by the session — so it goes to stdout and the process exits clean.
322	  console.log('converge-item: the transition below is yours to execute.\n'
323	    + 'Make these calls with your GitHub tools, in this order, changing nothing. Then stop.\n');
324	  console.log(sessionScript(item, plan, repo));
325	}
326	
327	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
328	  main().catch((e) => { console.error(e); process.exitCode = 1; });
329	}
